from pathlib import Path
import json,re,hashlib
root=Path('/home/ws/projects/verified-decoders/gif')
source=root/'spec-frozen/VECTORS.json'
vs=json.loads(source.read_text());want=['empty','header-12','bad-signature','version-88a','header-only-gct-trailer/still','two-colour-m2','basic-4x3-gct','basic-87a']
by={v['name']:v for v in vs};assert all(n in by for n in want)
seq=lambda xs:'seq!['+','.join(str(x)+'u8' for x in xs)+']'
out=['//! Initial integrated non-vacuity gates from frozen authored expectations.',
     '//! Generated by runs/sol-20261116/emit-initial-model-vectors.py, without an oracle or executable.',
     '//! VECTORS.json SHA-256 '+hashlib.sha256(source.read_bytes()).hexdigest(),
     'use vstd::prelude::*;','use crate::gif::{Error,Still};','use crate::alloc_guard::sites::TryError;',
     'verus! {']
for name in want:
 v=by[name];assert v['entry']=='still' and 'profile' not in v and 'repeat' not in v and 'pad_to' not in v
 b=bytes.fromhex(v['input_hex']);assert len(b)<=4096
 key=re.sub('[^a-z0-9]+','_',name).strip('_');e=v['expected'];bs=seq(b)
 if 'error' in e:
  expected='Some(Err(Error::'+e['error']+'))'
  result='match r {Err(TryError::Format(e))=>e==Error::'+e['error']+',_=>false}'
 else:
  rgba=b''.join(bytes.fromhex(run['hex'])*run['count'] for run in e['rgba_runs']);assert len(rgba)==4*e['width']*e['height'];rs=seq(rgba)
  expected=f"Some(Ok(crate::frame_model::StillImage {{width:{e['width']},height:{e['height']},rgba:{rs},recovered:false}}))"
  result=f"match r {{Ok(s)=>s.width=={e['width']} && s.height=={e['height']} && s.rgba@=={rs},_=>false}}"
 call=f'crate::frame_model::ms(bytes_{key}(),crate::policy::profile_record(crate::policy::Profile::Strict))'
 out += [f'// Frozen record {name}.',f'pub open spec fn bytes_{key}()->Seq<u8> {{{bs}}}',
         f'pub open spec fn expected_{key}(r:Result<Still,TryError>)->bool {{{result}}}',
         f'pub proof fn model_{key}()',f'    ensures {call}=={expected},','{',f'    assert({call}=={expected}) by(compute);','}',
         f'pub fn executable_{key}(b:&[u8])->(r:Result<Still,TryError>)',f'    requires b@==bytes_{key}(),',f'    ensures !(r is Err && r->Err_0 is OutOfMemory) ==> expected_{key}(r),','{',
         f'    proof {{model_{key}();}}','    let r=crate::gif::try_decode_still(b);','    proof {reveal(crate::gif::still_core_result);}','    r','}']
out+=['} // verus!','']
p=root/'gif_verus/src/model_vectors.rs';assert not p.exists();p.write_text('\n'.join(out));assert p.stat().st_size>0
print('Generated',len(want),'model/real-public-call witness pairs from authored expected fields')
